    <!-- Admission Process Section Starts -->

    <div class="admission-process pb-4 pb-lg-5 position-relative" id="admission-process">
        <div class="custom-container position-relative z-2">
            <div class="admission-grid">
                <div class="content-part">
                    <h2 class="heading-medium">Admission Process</h2>
                    <div class="para">
                        <strong>The program follows 4 simple steps.</strong> Selected candidates receive an admission
                        offer, confirmed after fee payment.
                    </div>
                    <ul class="list-unstyled listing">
                        <li class="d-flex gap-2 gap-lg-3 align-items-start">
                            <span class="number">01</span>
                            <p><span class="d-block">Submit Your Application</span>
                                Fill out the online form & our Admissions team will reach out within 24 hours.
                            </p>
                        </li>

                        <li class="d-flex gap-2 gap-lg-3 align-items-start">
                            <span class="number">02</span>
                            <p><span class="d-block">Profile Screening</span>
                                Our team reviews your background & assesses program fitment for the best results.
                            </p>
                        </li>

                        <li class="d-flex gap-2 gap-lg-3 align-items-start">
                            <span class="number">03</span>
                            <p><span class="d-block">Scholarship & Offer Letter</span>
                                Eligible candidates receive a merit-based scholarship offer & official admission letter.
                            </p>
                        </li>
                        <li class="d-flex gap-2 gap-lg-3 align-items-start">
                            <span class="number">04</span>
                            <p class="mb-0"><span class="d-block">Confirm Seat & Begin Learning</span>
                                Complete your fee payment, get login credentials & join your assigned batch immediately
                            </p>
                        </li>


                    </ul>
                </div>
                <div class="image-part d-flex justify-content-center ">
                    <img src="assets/dit/images/embedded-iot-sample/girl-admission.webp" class="img-fluid"
                        style="max-height: 428px;">
