    <script defer>
        window.requestIdleCallback =
            window.requestIdleCallback ||
            function(cb) {
                return setTimeout(cb, 1);
            };

        requestIdleCallback(() => {
            const swiperScript = document.createElement("script");
            swiperScript.src =
                "https://cdn.jsdelivr.net/npm/swiper@10/swiper-bundle.min.js";
            swiperScript.onload = () => {
                const configs = {
                    mySwiper1: 3,
                    mySwiper2: 2,
                    mySwiper4: 2,
                    mySwiper5: 3,
                    mySwiper6: 4,
                };

                Object.entries(configs).forEach(([className, slidesView]) => {
                    new Swiper(`.${className}`, {
                        slidesPerView: slidesView,
                        spaceBetween: 20,
                        loop: className === "mySwiper2" ? false : true,
                        freeMode: true,
                        breakpoints: {
                            280: {
                                slidesPerView: 1,
                                spaceBetween: 10
                            },
                            320: {
                                slidesPerView: 1,
                                spaceBetween: 10
                            },
                            480: {
                                slidesPerView: 2,
                                spaceBetween: 10
                            },
                            768: {
                                slidesPerView: className === "mySwiper1" ?
                                    2 : className === "mySwiper2" ?
                                    3 : slidesView,
                                spaceBetween: 10,
                            },
                            992: {
                                slidesPerView: slidesView,
                                spaceBetween: 10
                            },
                            1200: {
                                slidesPerView: slidesView,
                                spaceBetween: 20
                            },
                        },
                        autoplay: className === "mySwiper2" ?
                            false : {
                                delay: 3500,
                                disableOnInteraction: true,
                                pauseOnMouseEnter: true,
                            },
                        navigation: {
                            nextEl: `.swiper-button-next${className.slice(-1)}`,
                            prevEl: `.swiper-button-prev${className.slice(-1)}`,
                        },
                        pagination: {
                            el: `.swiper-pagination${className.slice(-1)}`,
                            clickable: true,
                        },
                    });
                });

                // ── Inject overlay + view button into every img-card ──
                document.querySelectorAll('.lab-gallery .mySwiper6 .img-card').forEach((card) => {
                    const overlay = document.createElement('div');
                    overlay.className = 'overlay';
                    overlay.innerHTML = `
                    <button class="view-btn" aria-label="View full image">
                        <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none">
                            <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" stroke="#00b6b1" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                        </svg>
                    </button>`;
                    card.appendChild(overlay);
                });

                // ── Lightbox logic ──
                const lb = document.getElementById('galleryLightbox');
                const lbImg = lb.querySelector('.lb-img');
                const lbClose = lb.querySelector('.lb-close');
                const lbPrev = lb.querySelector('.lb-prev');
                const lbNext = lb.querySelector('.lb-next');
                const lbCurrent = document.getElementById('lbCurrent');
                const lbTotal = document.getElementById('lbTotal');

                function getImageList() {
                    return Array.from(
                        document.querySelectorAll(
                            '.lab-gallery .mySwiper6 .swiper-slide:not(.swiper-slide-duplicate) .img-card img'
                        )
                    ).map(img => img.src);
                }

                let images = [];
                let currentIndex = 0;

                function openLightbox(src) {
                    images = getImageList();
                    currentIndex = images.indexOf(src);
                    if (currentIndex === -1) currentIndex = 0;
                    showImage(currentIndex);
                    lb.classList.add('active');
                    document.body.style.overflow = 'hidden';
                }

                function closeLightbox() {
                    lb.classList.remove('active');
                    document.body.style.overflow = '';
                }

                function showImage(index) {
                    lbImg.src = images[index];
                    lbCurrent.textContent = index + 1;
                    lbTotal.textContent = images.length;
                }

                function prevImage() {
                    currentIndex = (currentIndex - 1 + images.length) % images.length;
                    showImage(currentIndex);
                }

                function nextImage() {
                    currentIndex = (currentIndex + 1) % images.length;
                    showImage(currentIndex);
                }

                // Open on view-btn click
                document.querySelector('.lab-gallery .mySwiper6').addEventListener('click', (e) => {
                    const btn = e.target.closest('.view-btn');
                    if (!btn) return;
                    const img = btn.closest('.img-card').querySelector('img');
                    openLightbox(img.src);
                });

                lbClose.addEventListener('click', closeLightbox);
                lbPrev.addEventListener('click', prevImage);
                lbNext.addEventListener('click', nextImage);

                // Close on backdrop click
                lb.addEventListener('click', (e) => {
                    if (e.target === lb) closeLightbox();
                });

                // Keyboard navigation
                document.addEventListener('keydown', (e) => {
                    if (!lb.classList.contains('active')) return;
                    if (e.key === 'ArrowLeft') prevImage();
                    if (e.key === 'ArrowRight') nextImage();
                    if (e.key === 'Escape') closeLightbox();
                });
            };

            document.body.appendChild(swiperScript);
        });
    </script>

    <script defer>
        function getTimeRemaining(endTime) {
            const total = Date.parse(endTime) - Date.parse(new Date());
            const seconds = Math.floor((total / 1000) % 60);
            const minutes = Math.floor((total / 1000 / 60) % 60);
            const hours = Math.floor((total / (1000 * 60 * 60)) % 24);
            const days = Math.floor(total / (1000 * 60 * 60 * 24));

            return {
                total,
                days,
                hours,
                minutes,
                seconds
            };
        }

        function getEndTime() {
            return new Date(2026, 9, 15, 23, 59, 59);
        }

        function padZero(number) {
            return number < 10 ? '0' + number : number;
        }

        function initializeClock() {
            const countdownElement = document.getElementById('countdown');
            const countdownElement2 = document.getElementById('countdown2');
            const countdownElement3 = document.getElementById('countdown3');
            const countdownElement4 = document.getElementById('countdown4');
            const countdownElement5 = document.getElementById('countdown5');
            const countdownElement6 = document.getElementById('countdown6');

            // Add null check
            if (!countdownElement && !countdownElement2 && !countdownElement3 && !countdownElement4 && !countdownElement5 &&
                !countdownElement6) {
                console.warn('Countdown elements not found');
                return;
            }

            const endTime = getEndTime();

            function updateClock() {
                const t = getTimeRemaining(endTime);

                if (countdownElement) {
                    countdownElement.innerHTML = `
                            <p><span>${padZero(t.days)}</span>Days</p> :
                            <p><span>${padZero(t.hours)}</span>Hours</p> :
                            <p><span>${padZero(t.minutes)}</span>Minutes</p> :
                            <p><span>${padZero(t.seconds)}</span>Seconds</p>
                        `;
                }

                if (countdownElement2) {
                    countdownElement2.innerHTML = `
                                <div class="time-block">
                                    <span>${padZero(t.days)}</span>
                                    <small>Days</small>
                                </div>
                                <div class="colon">:</div>

                                <div class="time-block">
                                    <span>${padZero(t.hours)}</span>
                                    <small>Hours</small>
                                </div>
                                <div class="colon">:</div>

                                <div class="time-block">
                                    <span>${padZero(t.minutes)}</span>
                                    <small>Minutes</small>
                                </div>
                                <div class="colon">:</div>

                                <div class="time-block">
                                    <span>${padZero(t.seconds)}</span>
                                    <small>Seconds</small>
                                </div>
                            `;
                }

                if (countdownElement3) {
                    countdownElement3.innerHTML = `
                                <div class="time-block">
                                    <span>${padZero(t.days)}</span>
                                    <small>Days</small>
                                </div>
                                <div class="colon">:</div>

                                <div class="time-block">
                                    <span>${padZero(t.hours)}</span>
                                    <small>Hours</small>
                                </div>
                                <div class="colon">:</div>

                                <div class="time-block">
                                    <span>${padZero(t.minutes)}</span>
                                    <small>Minutes</small>
                                </div>
                                <div class="colon">:</div>

                                <div class="time-block">
                                    <span>${padZero(t.seconds)}</span>
                                    <small>Seconds</small>
                                </div>
                            `;
                }


                if (countdownElement4) {
                    countdownElement4.innerHTML = `
                                <div class="time-block">
                                    <span>${padZero(t.days)}</span>
